package com.gymmind.knowledge.infrastructure.search;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*;
@Component @ConditionalOnProperty(name="gymmind.search.backend",havingValue="elasticsearch") public class ElasticsearchKeywordIndex implements KeywordIndexPort { private final RestClient client; private final String index; private final ObjectMapper mapper=new ObjectMapper(); public ElasticsearchKeywordIndex(RestClient.Builder b){client=b.baseUrl(Optional.ofNullable(System.getenv("GYMMIND_ES_URL")).orElse("http://localhost:9200")).build();index=Optional.ofNullable(System.getenv("GYMMIND_ES_INDEX")).orElse("gymmind-knowledge");} public void upsert(IndexedChunk c){client.put().uri("/"+index+"/_doc/"+c.id()).body(Map.of("tenantId",c.tenantId(),"text",c.text())).retrieve().toBodilessEntity();} public List<IndexedChunk> search(String q,Long t){Map<String,Object> body=Map.of("query",Map.of("bool",Map.of("must",List.of(Map.of("match",Map.of("text",q))),"filter",List.of(Map.of("term",Map.of("tenantId",t))))),"size",30); String raw=client.post().uri("/"+index+"/_search").body(body).retrieve().body(String.class); if(raw==null)return List.of(); try {JsonNode hits=mapper.readTree(raw).path("hits").path("hits"); List<IndexedChunk> out=new ArrayList<>(); for(JsonNode h:hits){JsonNode s=h.path("_source"); out.add(new IndexedChunk(h.path("_id").asText(),s.path("tenantId").asLong(),s.path("text").asText(),null));} return out;} catch(Exception e){return List.of();} } public void delete(String id,Long t){client.delete().uri("/"+index+"/_doc/"+id).retrieve().toBodilessEntity();} }

